import OfferFetch from "../fetches/OfferFetch";
import Application, { Item } from "../models/Application";
export default class OfferController {
    constructor(view) {
        this.view = view;
    }
    async load(offerID) {
        const offer = await OfferFetch.get(offerID);
        console.log(offer);
        this.view.update(offer);
        this.model = offer;
    }
    isOfferMine() {
        if (!this.model)
            return false;
        const currentUser = Application.getInstance().get(Item.CurrentUser);
        return currentUser ? this.model.sellerID === currentUser._id : false;
    }
}
